// ── WF5: Formatear error para log y notificación ─────────────────────────
const err = $json;
const safe = s => String(s||'').replace(/'/g,"''");
const wfName = safe(err.workflow ? err.workflow.name : 'Desconocido');
const nodeName = safe(err.execution ? err.execution.lastNodeExecuted : 'Desconocido');
const errorMsg = safe(err.error ? (err.error.message || JSON.stringify(err.error)) : 'Error sin mensaje');
const errData = safe(JSON.stringify(err));

const sql_query = "INSERT INTO error_logs (workflow_name, node_name, error_message, error_data) VALUES ('" +
  wfName + "', '" + nodeName + "', '" + errorMsg + "', '" + errData + "')";

const emailSubject = '🚨 Error en Workflow: ' + (err.workflow ? err.workflow.name : 'Desconocido');
const emailBody = `<div style="font-family:Arial,sans-serif;max-width:560px">
  <div style="background:#dc2626;color:#fff;padding:18px;border-radius:8px 8px 0 0">
    <h2 style="margin:0">🚨 Error de Sistema</h2></div>
  <div style="background:#fff;padding:20px;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 8px 8px">
    <p><strong>Workflow:</strong> ${err.workflow ? err.workflow.name : 'N/A'}</p>
    <p><strong>Nodo:</strong> ${err.execution ? err.execution.lastNodeExecuted : 'N/A'}</p>
    <p><strong>Error:</strong> ${err.error ? (err.error.message || 'Sin mensaje') : 'N/A'}</p>
    <p style="color:#6b7280;font-size:12px">Revise el log de errores en la tabla error_logs de la BD.</p>
  </div></div>`;

return [{ json: { sql_query, emailSubject, emailBody, workflowName: wfName, errorMsg } }];
